export function getCardBySlug(slug: string): TarotCard | undefined {
  return tarotCards.find((c) => c.slug === slug);
}

export function getCardsByType(type: "major" | "minor"): TarotCard[] {
  return tarotCards.filter((c) => c.type === type);
}

export function getCardsBySuit(suit: string): TarotCard[] {
  return tarotCards.filter((c) => c.suit === suit);
}
